property.value:
let $words := function($s) {
      tokenize(lower-case(replace(replace(replace($s, '([a-z0-9])([A-Z])', '$1 $2'), '([A-Z]+)([A-Z][a-z])', '$1 $2'),
        '[^A-Za-z0-9]+', ' ')), ' ')[. != '']
    },
    $trimmed := function($n) {
      replace(string-join($words($n), ' '), '(?: (?:value|raw|str|string|text|plain))+$', '')
    },
    $secretName := function($n) {
      matches(replace($trimmed($n), '[ 0-9]', ''),
        '(?:password|passwd|pwd|passphrase|secret|token|credentials?|apikey|privatekey|accesskey|secretkey|authkey|signingkey|encryptionkey|hmackey|jwtkey)$')
      and not(matches($trimmed($n), '(?:^| )(?:eos|bos|pad|unk|cls|sep|mask|next|page|continuation|cancellation) token$')) and not(matches($trimmed($n), '(?:^| )(?:masked|redacted)(?: |$)'))
    },
    $loggedName := function($n) {
      $secretName($n) and not(matches($n, '^(?:has|is)[A-Z_]')) and not(matches($n, '^[A-Z][A-Z0-9_]*$'))
    },
    $secret := function($leaf) {
      exists($leaf[self::VariableAccess or self::FieldAccess][$loggedName(@Name)]
        | $leaf[self::MethodCall][ArgumentList/@Size = 0][matches(@MethodName, '^get[A-Z]')]
            [$loggedName(substring(@MethodName, 4))]
        | $leaf[self::MethodCall][@MethodName = ('getenv', 'getProperty')]
            [ArgumentList/*[1][self::StringLiteral][$secretName(@ConstValue)]]
        | $leaf[self::MethodCall][@MethodName = 'get'][*[1][self::VariableAccess or self::FieldAccess]
            [matches(@Name, '^(?:env|environment|props|properties|config|settings)$', 'i')]]
            [ArgumentList/*[1][self::StringLiteral][$secretName(@ConstValue)]])
    },
    $carried := function($leaf, $argument) {
      every $step in ($leaf/ancestor::* intersect $argument/descendant::*) satisfies
        exists($step[self::InfixExpression[@Operator = '+'] or self::ConditionalExpression or self::CastExpression
          or self::MethodCall[@MethodName = ('valueOf', 'toString', 'copyValueOf', 'format', 'formatted', 'trim', 'strip',
                                              'toUpperCase', 'toLowerCase', 'of', 'ofNullable', 'toCharArray', 'concat')]
          or self::ConstructorCall[ClassType/@SimpleName = 'String'] or self::ArgumentList])
    },
    $logged := function($call) {
      let $receiver := $call/*[1]
      return $call/@MethodName = ('trace', 'debug', 'info', 'warn', 'error', 'fatal', 'log', 'severe', 'warning',
                                  'fine', 'finer', 'finest', 'atInfo', 'atWarn', 'atError', 'atDebug', 'atTrace')
        and (exists($receiver[self::MethodCall][@MethodName = ('getLogger', 'getLog')])
        or exists($receiver[self::VariableAccess or self::FieldAccess]
          [@Name = ('log', 'logger', 'LOG', 'LOGGER', 'LOGGING', 'slf4jLogger')
           or pmd-java:typeIs('org.slf4j.Logger') or pmd-java:typeIs('org.apache.logging.log4j.Logger')
           or pmd-java:typeIs('java.util.logging.Logger') or pmd-java:typeIs('org.apache.commons.logging.Log')
           or pmd-java:typeIs('org.jboss.logging.BasicLogger')]))
    },
    $console := function($call) {
      $call/@MethodName = ('print', 'println', 'printf', 'format')
        and exists($call/*[1][self::FieldAccess][@Name = ('out', 'err')]/*[1][self::TypeExpression/ClassType/@SimpleName = 'System'])
    },
    $keyed := function($call) {
      $call/@MethodName = ('addKeyValue', 'put') and $call/ArgumentList/@Size = 2
        and $call/ArgumentList/*[1][self::StringLiteral][$secretName(@ConstValue)]
        and not($call/ArgumentList/*[2][self::StringLiteral])
        and ($call/@MethodName = 'addKeyValue' or exists($call/*[1][self::TypeExpression/ClassType/@SimpleName = 'MDC']))
    }
return (
  for $call in //MethodCall[$logged(.) or $console(.)],
      $leaf in $call/ArgumentList/*/descendant-or-self::*[$secret(.)][$carried(., $call/ArgumentList)]
  return $leaf
  ,
  for $call in //ConstructorCall[ClassType[matches(@SimpleName, '(?:Exception|Error)$')]],
      $leaf in $call/ArgumentList/*/descendant-or-self::*[$secret(.)][$carried(., $call/ArgumentList)]
  return $leaf
  ,
  for $call in //MethodCall[$keyed(.)]
  return $call/ArgumentList/*[2]
)
